    69				last := &blocks[len(blocks)-1]
    70				if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
    71					last.EndLine = block.EndLine
    72					last.CodeLines = append(last.CodeLines, block.CodeLines...)
